-- [
  {
    "section": "FUNCTIONS",
    "name": "cb_conversation_embeddings_set_project_id",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_conversation_embeddings_set_project_id()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\r\nbegin\r\n  if new.project_id is null then\r\n    select c.project_id into new.project_id\r\n    from public.cb_conversations c\r\n    where c.id = new.conversation_id;\r\n\r\n    if new.project_id is null then\r\n      raise exception 'Could not derive project_id for conversation_id=%', new.conversation_id;\r\n    end if;\r\n  end if;\r\n  return new;\r\nend;\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_conversations_ensure_project",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_conversations_ensure_project()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\r\nbegin\r\n  if not exists (select 1 from public.cb_projects pr where pr.id = new.project_id) then\r\n    insert into public.cb_projects (id, name, provider, provider_project_id, created_at)\r\n    values (new.project_id, coalesce(nullif(new.title,''), 'Captured Project'), 'claude', 'claude/auto', now())\r\n    on conflict (id) do nothing;\r\n  end if;\r\n  return new;\r\nend;\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_embedding_progress",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_embedding_progress(p_project_id uuid)\n RETURNS TABLE(project_id uuid, msg_total bigint, msg_pending bigint, file_total bigint, file_pending bigint, block_total bigint, block_pending bigint)\n LANGUAGE sql\nAS $function$\r\n  with\r\n  m_tot as (\r\n    select count(*)::bigint cnt from public.cb_messages where project_id = p_project_id\r\n  ),\r\n  m_pen as (\r\n    select count(*)::bigint cnt from public.v_cb_messages_needing_embeddings where project_id = p_project_id\r\n  ),\r\n  f_tot as (\r\n    select count(*)::bigint cnt from public.cb_files where project_id = p_project_id\r\n  ),\r\n  f_pen as (\r\n    select count(*)::bigint cnt from public.v_cb_files_needing_embeddings where project_id = p_project_id\r\n  ),\r\n  b_tot as (\r\n    select count(*)::bigint cnt\r\n    from public.cb_blocks b\r\n    join public.cb_messages m on m.id = b.message_id\r\n    where m.project_id = p_project_id\r\n  ),\r\n  b_pen as (\r\n    select count(*)::bigint cnt from public.v_cb_blocks_needing_embeddings where project_id = p_project_id\r\n  )\r\n  select\r\n    p_project_id,\r\n    (select cnt from m_tot)   as msg_total,\r\n    (select cnt from m_pen)   as msg_pending,\r\n    (select cnt from f_tot)   as file_total,\r\n    (select cnt from f_pen)   as file_pending,\r\n    (select cnt from b_tot)   as block_total,\r\n    (select cnt from b_pen)   as block_pending;\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_extract_entities_from_conversation",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_extract_entities_from_conversation(p_project_id uuid, p_conversation_id uuid, p_text text)\n RETURNS jsonb\n LANGUAGE plpgsql\nAS $function$\r\nDECLARE\r\n  v_entity_count INT := 0;\r\n  v_mention_count INT := 0;\r\n  v_entity_id uuid;\r\n  v_entity_record RECORD;\r\nBEGIN\r\n  -- Extract file paths (e.g., src/components/Button.tsx)\r\n  FOR v_entity_record IN\r\n    SELECT DISTINCT\r\n      regexp_matches[1] as entity_name,\r\n      'file' as entity_type\r\n    FROM regexp_matches(p_text, '(?:^|\\s|[`''\"])((?:[a-zA-Z0-9_-]+/)+[a-zA-Z0-9_.-]+\\.[a-zA-Z0-9]+)', 'g') AS regexp_matches\r\n    WHERE length(regexp_matches[1]) BETWEEN 5 AND 200\r\n  LOOP\r\n    -- Use cb_upsert_entity_mention to create entity AND mention\r\n    -- Note: We don't have message_id here since we're processing full conversation\r\n    -- So we'll create entity but link mention to conversation via message lookup later\r\n    -- For now, just create the entity\r\n    v_entity_id := cb_upsert_entity_mention(\r\n      p_project_id,\r\n      v_entity_record.entity_name,\r\n      v_entity_record.entity_type,\r\n      NULL, -- message_id (will be NULL for conversation-level extraction)\r\n      NULL, -- cb_file_id\r\n      NULL, -- block_id\r\n      substring(p_text, 1, 200) -- snippet\r\n    );\r\n    \r\n    v_entity_count := v_entity_count + 1;\r\n    v_mention_count := v_mention_count + 1;\r\n  END LOOP;\r\n\r\n  -- Extract technologies (e.g., React, TypeScript, PostgreSQL)\r\n  FOR v_entity_record IN\r\n    SELECT DISTINCT\r\n      word as entity_name,\r\n      'technology' as entity_type\r\n    FROM (\r\n      SELECT unnest(regexp_matches(p_text, '\\b(React|TypeScript|JavaScript|Node\\.js|Express|Supabase|PostgreSQL|Python|Django|FastAPI|Vue|Angular|Next\\.js|Tailwind|Docker|Kubernetes|AWS|Azure|GCP|MongoDB|Redis|GraphQL|REST|API|SQL|NoSQL|Git|GitHub|GitLab|Vercel|Netlify|Claude|OpenAI|Anthropic|Chrome|Extension)\\b', 'gi')) as word\r\n    ) AS words\r\n  LOOP\r\n    v_entity_id := cb_upsert_entity_mention(\r\n      p_project_id,\r\n      v_entity_record.entity_name,\r\n      v_entity_record.entity_type,\r\n      NULL,\r\n      NULL,\r\n      NULL,\r\n      substring(p_text, 1, 200)\r\n    );\r\n    \r\n    v_entity_count := v_entity_count + 1;\r\n    v_mention_count := v_mention_count + 1;\r\n  END LOOP;\r\n\r\n  -- Return summary\r\n  RETURN jsonb_build_object(\r\n    'success', true,\r\n    'entities_extracted', v_entity_count,\r\n    'mentions_created', v_mention_count,\r\n    'project_id', p_project_id,\r\n    'conversation_id', p_conversation_id,\r\n    'text_length', length(p_text)\r\n  );\r\n  \r\nEXCEPTION WHEN OTHERS THEN\r\n  RETURN jsonb_build_object(\r\n    'success', false,\r\n    'error', SQLERRM,\r\n    'project_id', p_project_id,\r\n    'conversation_id', p_conversation_id\r\n  );\r\nEND;\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_files_columns",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_files_columns()\n RETURNS TABLE(path_col text, content_col text, updated_col text)\n LANGUAGE plpgsql\nAS $function$\r\ndeclare\r\n  rel regclass := cb_resolve_files_table();\r\n  schema_name text;\r\n  rel_name text;\r\n\r\n  -- Fallback candidates (used only if table ≠ public.cb_files)\r\n  path_candidates    text[] := array['path','file_path','filepath','full_path','rel_path','relative_path','repo_path','name','filename','file_name','key','uri','url'];\r\n  content_candidates text[] := array['content','contents','body','text','raw','data','source','markdown','md','code'];\r\n  updated_candidates text[] := array['updated_at','modified_at','last_modified','last_update','mtime','updated','modified','timestamp','ts','created_at','inserted_at','created'];\r\n\r\n  col record;\r\nbegin\r\n  -- Resolve schema.table\r\n  select n.nspname, pc.relname\r\n    into schema_name, rel_name\r\n  from pg_class pc\r\n  join pg_namespace n on n.oid = pc.relnamespace\r\n  where pc.oid = rel;\r\n\r\n  if schema_name is null then\r\n    raise exception 'Could not resolve schema for %', rel::text;\r\n  end if;\r\n\r\n  -- Fast path: your known schema/table\r\n  if schema_name = 'public' and rel_name = 'cb_files' then\r\n    return query select 'file_name'::text, 'content'::text, 'created_at'::text;\r\n    return;\r\n  end if;\r\n\r\n  -- -------- Fallback (for other tables) --------\r\n  -- Exact-match pass\r\n  for col in\r\n    select column_name\r\n    from information_schema.columns\r\n    where table_schema = schema_name and table_name = rel_name\r\n  loop\r\n    if path_col    is null and col.column_name = any(path_candidates)    then path_col    := col.column_name; end if;\r\n    if content_col is null and col.column_name = any(content_candidates) then content_col := col.column_name; end if;\r\n    if updated_col is null and col.column_name = any(updated_candidates) then updated_col := col.column_name; end if;\r\n  end loop;\r\n\r\n  -- Fuzzy pass (ILIKE)\r\n  if path_col is null then\r\n    select column_name into path_col\r\n    from information_schema.columns\r\n    where table_schema = schema_name and table_name = rel_name\r\n      and data_type in ('text','character varying')\r\n      and (column_name ilike any(array['%path%','%file%','%name%','%uri%','%url%','%key%']))\r\n    order by\r\n      (case when column_name ilike '%path%' then 1\r\n            when column_name ilike '%file%' then 2\r\n            when column_name ilike '%name%' then 3\r\n            when column_name ilike '%uri%'  then 4\r\n            when column_name ilike '%url%'  then 5\r\n            when column_name ilike '%key%'  then 6\r\n            else 7 end)\r\n    limit 1;\r\n  end if;\r\n\r\n  if content_col is null then\r\n    select column_name into content_col\r\n    from information_schema.columns\r\n    where table_schema = schema_name and table_name = rel_name\r\n      and data_type in ('text','character varying')\r\n      and (column_name ilike any(array['%content%','%text%','%body%','%raw%','%data%','%source%','%code%','%markdown%','%md%']))\r\n    order by\r\n      (case when column_name ilike '%content%' then 1\r\n            when column_name ilike '%text%'    then 2\r\n            when column_name ilike '%body%'    then 3\r\n            when column_name ilike '%raw%'     then 4\r\n            when column_name ilike '%data%'    then 5\r\n            when column_name ilike '%source%'  then 6\r\n            when column_name ilike '%code%'    then 7\r\n            when column_name ilike '%markdown%' then 8\r\n            when column_name ilike '%md%'      then 9\r\n            else 10 end)\r\n    limit 1;\r\n  end if;\r\n\r\n  if updated_col is null then\r\n    select column_name into updated_col\r\n    from information_schema.columns\r\n    where table_schema = schema_name and table_name = rel_name\r\n      and data_type like 'timestamp%'\r\n      and (column_name ilike any(array['%updated%','%modified%','%created%','%timestamp%','%inserted%','%time%','%ts%']))\r\n    order by\r\n      (case when column_name ilike '%updated%'   then 1\r\n            when column_name ilike '%modified%'  then 2\r\n            when column_name ilike '%created%'   then 3\r\n            when column_name ilike '%timestamp%' then 4\r\n            when column_name ilike '%inserted%'  then 5\r\n            when column_name ilike '%time%'      then 6\r\n            when column_name ilike '%ts%'        then 7\r\n            else 8 end)\r\n    limit 1;\r\n  end if;\r\n\r\n  -- Emit one row (or error if impossible)\r\n  if path_col is null or content_col is null or updated_col is null then\r\n    raise exception 'Could not resolve path/content/updated columns for %.%', schema_name, rel_name;\r\n  end if;\r\n\r\n  return query select path_col, content_col, updated_col;\r\nend;\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_find_code_spans",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_find_code_spans(p_project_id uuid, p_q text, p_window_lines integer DEFAULT 6, p_max_results integer DEFAULT 25)\n RETURNS TABLE(path text, start_line integer, end_line integer, snippet text, score real, updated_at timestamp with time zone)\n LANGUAGE plpgsql\n STABLE\nAS $function$\r\ndeclare\r\n  files_tbl regclass := cb_resolve_files_table();\r\n  cols record;\r\n  sql text;\r\nbegin\r\n  if p_q is null or length(trim(p_q)) = 0 then\r\n    return;\r\n  end if;\r\n\r\n  select * into cols from cb_files_columns();\r\n\r\n  sql := format($f$\r\n    with latest as (\r\n      select *\r\n      from (\r\n        select f.*,\r\n               row_number() over (partition by %1$I order by %3$I desc nulls last) as rn\r\n        from %6$s f\r\n        where f.project_id = %7$L::uuid\r\n      ) x\r\n      where rn = 1\r\n    ),\r\n    base as (\r\n      select\r\n        %1$I as path,\r\n        %2$I as content,\r\n        %3$I as updated_at,\r\n        case\r\n          when position(lower(%4$L) in lower(%2$I)) > 0 then 0.6 else 0\r\n        end\r\n        + greatest(\r\n            similarity(lower(%1$I), lower(%4$L)) * 0.3,\r\n            similarity(lower(split_part(%1$I, '/', array_length(string_to_array(%1$I,'/'),1))), lower(%4$L)) * 0.4\r\n          ) as score,\r\n        position(lower(%4$L) in lower(%2$I)) as pos\r\n      from latest\r\n    ),\r\n    hits as (\r\n      select\r\n        path,\r\n        updated_at,\r\n        score,\r\n        pos,\r\n        case\r\n          when pos > 0 then\r\n            1 + length(substring(content from 1 for pos)) - length(replace(substring(content from 1 for pos), E'\\n', ''))\r\n          else null\r\n        end as line_no,\r\n        content\r\n      from base\r\n      where pos > 0\r\n    ),\r\n    windowed as (\r\n      select\r\n        path,\r\n        updated_at,\r\n        score,\r\n        greatest(1, line_no - %5$s) as start_line,\r\n        (line_no + %5$s) as end_line,\r\n        content\r\n      from hits\r\n    ),\r\n    sliced as (\r\n      select\r\n        w.path,\r\n        w.updated_at,\r\n        w.score,\r\n        w.start_line,\r\n        w.end_line,\r\n        coalesce(string_agg(\r\n          case when trim(l) = '' then null else l end,\r\n          E'\\n'\r\n          order by n\r\n        ), '') as snippet\r\n      from windowed w\r\n      cross join lateral regexp_split_to_table(w.content, E'\\n') with ordinality as t(l, n)\r\n      where n between w.start_line and w.end_line\r\n      group by w.path, w.updated_at, w.score, w.start_line, w.end_line\r\n    )\r\n    select\r\n      path,\r\n      start_line,\r\n      end_line,\r\n      snippet,\r\n      score::real,\r\n      updated_at\r\n    from sliced\r\n    order by score desc, updated_at desc\r\n    limit %8$s\r\n  $f$,\r\n    cols.path_col,          -- %1$I\r\n    cols.content_col,       -- %2$I\r\n    cols.updated_col,       -- %3$I\r\n    p_q,                    -- %4$L\r\n    p_window_lines::text,   -- %5$s\r\n    files_tbl::text,        -- %6$s\r\n    p_project_id::text,     -- %7$L\r\n    p_max_results::text     -- %8$s\r\n  );\r\n\r\n  return query execute sql;\r\nend;\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_find_files",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_find_files(p_project_id uuid, p_q text, p_max_results integer DEFAULT 50)\n RETURNS TABLE(path text, filename text, dir text, score real, updated_at timestamp with time zone)\n LANGUAGE plpgsql\n STABLE\nAS $function$\r\ndeclare\r\n  files_tbl regclass := cb_resolve_files_table();\r\n  cols record;\r\n  sql text;\r\nbegin\r\n  if p_q is null or length(trim(p_q)) = 0 then\r\n    return;\r\n  end if;\r\n\r\n  select * into cols from cb_files_columns();  -- resolves (file_name, content, created_at) in your schema\r\n\r\n  sql := format($f$\r\n    with latest as (\r\n      select *\r\n      from (\r\n        select f.*,\r\n               row_number() over (partition by %1$I order by %3$I desc nulls last) as rn\r\n        from %4$s f\r\n        where f.project_id = %5$L::uuid\r\n      ) x\r\n      where rn = 1\r\n    ),\r\n    norm as (\r\n      select\r\n        %1$I as path,\r\n        split_part(%1$I, '/', array_length(string_to_array(%1$I,'/'),1)) as filename,\r\n        regexp_replace(%1$I, '/[^/]+$', '', 1, 1) as dir,\r\n        %3$I as updated_at\r\n      from latest\r\n    ),\r\n    -- make a weighted tsvector: filename = 'A', directory = 'B'\r\n    vec as (\r\n      select\r\n        path,\r\n        filename,\r\n        nullif(dir,'') as dir,\r\n        updated_at,\r\n        setweight(to_tsvector('simple', unaccent(lower(filename))), 'A')\r\n        ||\r\n        setweight(to_tsvector('simple', unaccent(lower(coalesce(dir,'')))), 'B')  as tsv\r\n      from norm\r\n    ),\r\n    -- build a prefix tsquery like: token1:* & token2:* ...\r\n    q as (\r\n      select to_tsquery('simple',\r\n               array_to_string(\r\n                 array_remove(regexp_split_to_array(unaccent(lower(%2$L)), '\\s+'), ''),\r\n                 ' & '\r\n               ) || case when trim(%2$L) <> '' then ':*' else '' end\r\n             ) as tsq,\r\n             unaccent(lower(%2$L)) as qtxt\r\n    ),\r\n    scored as (\r\n      select\r\n        v.path,\r\n        v.filename,\r\n        v.dir,\r\n        v.updated_at,\r\n        -- 1) filename similarity (highest weight)\r\n        similarity(lower(v.filename), (select qtxt from q))                               * 0.45\r\n        +\r\n        -- 2) word-similarity on filename (pg_trgm handles token-like closeness)\r\n        word_similarity(lower(v.filename), (select qtxt from q))                          * 0.30\r\n        +\r\n        -- 3) full-path similarity (helps when user pastes a whole/partial path)\r\n        similarity(lower(v.path), (select qtxt from q))                                   * 0.20\r\n        +\r\n        -- 4) weighted full-text rank (filename gets A-weight > dir)\r\n        ts_rank_cd(v.tsv, (select tsq from q))                                            * 0.35\r\n        as score\r\n      from vec v\r\n      where\r\n        -- keep candidates reasonably close\r\n        similarity(lower(v.filename), (select qtxt from q)) > 0.1\r\n        or similarity(lower(v.path), (select qtxt from q)) > 0.1\r\n        or (select tsq from q) @@ v.tsv\r\n    )\r\n    select\r\n      path,\r\n      filename,\r\n      coalesce(dir, '') as dir,\r\n      score::real,\r\n      updated_at\r\n    from scored\r\n    order by score desc, updated_at desc\r\n    limit %6$s\r\n  $f$,\r\n    cols.path_col,          -- %1$I  (file_name in your schema)\r\n    p_q,                    -- %2$L  (query text)\r\n    cols.updated_col,       -- %3$I  (created_at in your schema)\r\n    files_tbl::text,        -- %4$s  (public.cb_files)\r\n    p_project_id::text,     -- %5$L\r\n    p_max_results::text     -- %6$s\r\n  );\r\n\r\n  return query execute sql;\r\nend;\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_find_text_spans",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_find_text_spans(p_project_id uuid, p_q text, p_window_lines integer DEFAULT 8, p_max_results integer DEFAULT 30)\n RETURNS TABLE(path text, start_line integer, end_line integer, snippet text, score real, updated_at timestamp with time zone)\n LANGUAGE plpgsql\n STABLE\nAS $function$\r\ndeclare\r\n  files_tbl regclass := cb_resolve_files_table();\r\n  cols record;\r\n  sql text;\r\nbegin\r\n  if p_q is null or length(trim(p_q)) = 0 then return; end if;\r\n\r\n  select * into cols from cb_files_columns();\r\n\r\n  sql := format($f$\r\n    with latest as (\r\n      select *\r\n      from (\r\n        select f.*,\r\n               row_number() over (partition by %1$I order by %3$I desc nulls last) as rn\r\n        from %4$s f\r\n        where f.project_id = %5$L::uuid\r\n          and coalesce(lower(f.file_type), '') in ('document','text','data')\r\n          or lower(coalesce(f.file_extension,'')) in ('md','txt','pdf','docx','csv','json','yaml','yml')\r\n      ) x\r\n      where rn = 1\r\n    ),\r\n    base as (\r\n      select\r\n        %1$I as path,\r\n        %2$I as content,\r\n        %3$I as updated_at,\r\n        case when position(lower(%6$L) in lower(%2$I)) > 0 then 0.6 else 0 end\r\n        + greatest(similarity(lower(%1$I), lower(%6$L)) * 0.3, 0) as score,\r\n        position(lower(%6$L) in lower(%2$I)) as pos\r\n      from latest\r\n    ),\r\n    hits as (\r\n      select\r\n        path, updated_at, score, pos,\r\n        case when pos > 0 then 1 + length(substring(content from 1 for pos)) - length(replace(substring(content from 1 for pos), E'\\n', ''))\r\n             else null end as line_no,\r\n        content\r\n      from base\r\n      where pos > 0\r\n    ),\r\n    windowed as (\r\n      select\r\n        path, updated_at, score,\r\n        greatest(1, line_no - %7$s) as start_line,\r\n        (line_no + %7$s) as end_line,\r\n        content\r\n      from hits\r\n    ),\r\n    sliced as (\r\n      select\r\n        w.path, w.updated_at, w.score, w.start_line, w.end_line,\r\n        string_agg(l, E'\\n' order by n) as snippet\r\n      from windowed w\r\n      cross join lateral regexp_split_to_table(w.content, E'\\n') with ordinality as t(l, n)\r\n      where n between w.start_line and w.end_line\r\n      group by w.path, w.updated_at, w.score, w.start_line, w.end_line\r\n    )\r\n    select path, start_line, end_line, snippet, score::real, updated_at\r\n    from sliced\r\n    order by score desc, updated_at desc\r\n    limit %8$s\r\n  $f$,\r\n    cols.path_col, cols.content_col, cols.updated_col,\r\n    files_tbl::text, p_project_id::text,\r\n    p_q, p_window_lines::text, p_max_results::text\r\n  );\r\n\r\n  return query execute sql;\r\nend;\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_generate_relationships_for_conversation",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_generate_relationships_for_conversation(p_project_id uuid, p_conversation_id uuid DEFAULT NULL::uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\nAS $function$\r\nDECLARE\r\n  v_relationship_count int := 0;\r\n  v_rec record;\r\nBEGIN\r\n  -- Find entity pairs that co-occur in messages\r\n  FOR v_rec IN\r\n    WITH entity_pairs AS (\r\n      SELECT DISTINCT\r\n        e1.entity_id as subject_id,\r\n        e2.entity_id as object_id,\r\n        COUNT(*) as co_occurrence_count\r\n      FROM cb_entity_mentions e1\r\n      JOIN cb_entity_mentions e2 ON e1.message_id = e2.message_id AND e1.entity_id < e2.entity_id\r\n      WHERE e1.project_id = p_project_id\r\n        AND e2.project_id = p_project_id\r\n        AND (p_conversation_id IS NULL OR EXISTS (\r\n          SELECT 1 FROM cb_messages m \r\n          WHERE m.id = e1.message_id \r\n            AND m.conversation_id = p_conversation_id\r\n        ))\r\n      GROUP BY e1.entity_id, e2.entity_id\r\n      HAVING COUNT(*) > 0\r\n    )\r\n    SELECT * FROM entity_pairs\r\n  LOOP\r\n    -- Upsert relationship\r\n    INSERT INTO relationships (\r\n      project_id, \r\n      subject_entity_id, \r\n      predicate, \r\n      object_entity_id,\r\n      strength,\r\n      first_seen,\r\n      last_seen,\r\n      created_at,\r\n      updated_at\r\n    )\r\n    VALUES (\r\n      p_project_id,\r\n      v_rec.subject_id,\r\n      'co_occurs_with',\r\n      v_rec.object_id,\r\n      LEAST(v_rec.co_occurrence_count / 10.0, 1.0), -- Normalize strength 0-1\r\n      now(),\r\n      now(),\r\n      now(),\r\n      now()\r\n    )\r\n    ON CONFLICT (project_id, subject_entity_id, predicate, object_entity_id)\r\n    DO UPDATE SET\r\n      strength = LEAST((relationships.strength + EXCLUDED.strength) / 2, 1.0),\r\n      last_seen = now(),\r\n      updated_at = now();\r\n    \r\n    v_relationship_count := v_relationship_count + 1;\r\n  END LOOP;\r\n\r\n  RETURN jsonb_build_object(\r\n    'success', true,\r\n    'project_id', p_project_id,\r\n    'relationships_created', v_relationship_count\r\n  );\r\n  \r\nEXCEPTION WHEN OTHERS THEN\r\n  RETURN jsonb_build_object(\r\n    'success', false,\r\n    'error', sqlerrm\r\n  );\r\nEND;\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_get_latest_files",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_get_latest_files(p_project_id uuid, p_paths text[])\n RETURNS TABLE(path text, content text, updated_at timestamp with time zone)\n LANGUAGE plpgsql\n STABLE\nAS $function$\r\ndeclare\r\n  files_tbl regclass := cb_resolve_files_table();\r\n  cols record;\r\n  sql text;\r\nbegin\r\n  if p_paths is null or array_length(p_paths,1) is null then\r\n    return;\r\n  end if;\r\n\r\n  select * into cols from cb_files_columns();  -- (file_name, content, created_at) in your schema\r\n\r\n  sql := format($f$\r\n    with latest as (\r\n      select *\r\n      from (\r\n        select f.*,\r\n               row_number() over (partition by %1$I order by %3$I desc nulls last) as rn\r\n        from %4$s f\r\n        where f.project_id = %5$L::uuid\r\n          and %1$I = any(%6$L::text[])\r\n      ) x\r\n      where rn = 1\r\n    )\r\n    select\r\n      %1$I as path,\r\n      %2$I as content,\r\n      %3$I as updated_at\r\n    from latest\r\n  $f$,\r\n    cols.path_col,            -- %1$I  file_name\r\n    cols.content_col,         -- %2$I  content\r\n    cols.updated_col,         -- %3$I  created_at\r\n    files_tbl::text,          -- %4$s  public.cb_files\r\n    p_project_id::text,       -- %5$L\r\n    p_paths::text             -- %6$L  (array literal)\r\n  );\r\n\r\n  return query execute sql;\r\nend;\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_list_due_targets",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_list_due_targets(now_ts timestamp with time zone)\n RETURNS SETOF cb_capture_targets\n LANGUAGE sql\n STABLE\nAS $function$\r\n  select *\r\n  from cb_capture_targets\r\n  where is_enabled\r\n    and (\r\n      last_captured_at is null\r\n      or (now_ts - last_captured_at) > make_interval(mins => frequency_minutes)\r\n    )\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_list_routes",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_list_routes(p_project_id uuid, p_max_results integer DEFAULT 500)\n RETURNS TABLE(file_path text, method text, route text, updated_at timestamp with time zone)\n LANGUAGE plpgsql\n STABLE\nAS $function$\r\ndeclare\r\n  files_tbl regclass := cb_resolve_files_table();\r\n  cols record;\r\n  sql text;\r\nbegin\r\n  select * into cols from cb_files_columns();\r\n\r\n  sql := format($f$\r\n    with latest as (\r\n      select *\r\n      from (\r\n        select f.*,\r\n               row_number() over (partition by %1$I order by %3$I desc nulls last) as rn\r\n        from %4$s f\r\n        where f.project_id = %5$L::uuid\r\n      ) x\r\n      where rn = 1\r\n    ),\r\n    hits as (\r\n      select\r\n        %1$I as file_path,\r\n        %3$I as updated_at,\r\n        (regexp_matches(%2$I, '(?:router|app)\\.(get|post|put|delete|patch)\\s*\\(\\s*[''\"]([^''\"]+)[''\"]', 'gi'))[1] as method,\r\n        (regexp_matches(%2$I, '(?:router|app)\\.(get|post|put|delete|patch)\\s*\\(\\s*[''\"]([^''\"]+)[''\"]', 'gi'))[2] as route\r\n      from latest\r\n    )\r\n    select file_path, method, route, updated_at\r\n    from hits\r\n    where route is not null\r\n    limit %6$s\r\n  $f$,\r\n    cols.path_col,\r\n    cols.content_col,\r\n    cols.updated_col,\r\n    files_tbl::text,\r\n    p_project_id::text,\r\n    p_max_results::text\r\n  );\r\n\r\n  return query execute sql;\r\nend;\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_list_symbols_js",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_list_symbols_js(p_project_id uuid, p_max_results integer DEFAULT 1500)\n RETURNS TABLE(file_path text, kind text, name text, line integer, updated_at timestamp with time zone)\n LANGUAGE plpgsql\n STABLE\nAS $function$\r\ndeclare\r\n  files_tbl regclass := cb_resolve_files_table();\r\n  cols record;\r\n  sql text;\r\nbegin\r\n  select * into cols from cb_files_columns();\r\n\r\n  sql := format($f$\r\n    with latest as (\r\n      select *\r\n      from (\r\n        select f.*,\r\n               row_number() over (partition by %1$I order by %3$I desc nulls last) as rn\r\n        from %4$s f\r\n        where f.project_id = %5$L::uuid\r\n          and lower(coalesce(f.file_extension,'')) in ('js','jsx','ts','tsx')\r\n      ) x\r\n      where rn = 1\r\n    ),\r\n    lines as (\r\n      select\r\n        %1$I as file_path,\r\n        %3$I as updated_at,\r\n        regexp_split_to_table(%2$I, E'\\n') with ordinality as (line_text, n)\r\n      from latest\r\n    ),\r\n    comps as (\r\n      select file_path, 'component'::text as kind,\r\n             coalesce(\r\n               (regexp_matches(line_text, 'export\\s+default\\s+function\\s+([A-Za-z0-9_]+)\\s*\\('))[1],\r\n               (regexp_matches(line_text, 'function\\s+([A-Za-z0-9_]+)\\s*\\([^)]*\\)\\s*{'))[1],\r\n               (regexp_matches(line_text, 'export\\s+default\\s+([A-Za-z0-9_]+)\\s*=\\s*\\('))[1],\r\n               (regexp_matches(line_text, 'const\\s+([A-Za-z0-9_]+)\\s*=\\s*\\('))[1]\r\n             ) as name,\r\n             n as line, updated_at\r\n      from lines\r\n      where line_text ~ 'function\\s+[A-Za-z_]' or line_text ~ 'export\\s+default'\r\n    ),\r\n    exps as (\r\n      select file_path, 'export'::text as kind,\r\n             (regexp_matches(line_text, 'export\\s+(?:const|function|class)\\s+([A-Za-z0-9_]+)'))[1] as name,\r\n             n as line, updated_at\r\n      from lines\r\n      where line_text ~ 'export\\s+(const|function|class)\\s+[A-Za-z_]'\r\n    )\r\n    select * from comps where name is not null\r\n    union all\r\n    select * from exps  where name is not null\r\n    limit %6$s\r\n  $f$,\r\n    cols.path_col, cols.content_col, cols.updated_col,\r\n    files_tbl::text, p_project_id::text, p_max_results::text\r\n  );\r\n\r\n  return query execute sql;\r\nend;\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_list_symbols_md",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_list_symbols_md(p_project_id uuid, p_max_results integer DEFAULT 1500)\n RETURNS TABLE(file_path text, kind text, name text, line integer, updated_at timestamp with time zone)\n LANGUAGE plpgsql\n STABLE\nAS $function$\r\ndeclare\r\n  files_tbl regclass := cb_resolve_files_table();\r\n  cols record;\r\n  sql text;\r\nbegin\r\n  select * into cols from cb_files_columns();\r\n\r\n  sql := format($f$\r\n    with latest as (\r\n      select *\r\n      from (\r\n        select f.*,\r\n               row_number() over (partition by %1$I order by %3$I desc nulls last) as rn\r\n        from %4$s f\r\n        where f.project_id = %5$L::uuid\r\n          and lower(coalesce(f.file_extension,'')) in ('md','markdown')\r\n      ) x\r\n      where rn = 1\r\n    ),\r\n    lines as (\r\n      select\r\n        %1$I as file_path,\r\n        %3$I as updated_at,\r\n        regexp_split_to_table(%2$I, E'\\n') with ordinality as (line_text, n)\r\n      from latest\r\n    ),\r\n    heads as (\r\n      select file_path, 'heading'::text as kind,\r\n             (regexp_matches(line_text, '^\\s*#+\\s+(.+)\\s*$'))[1] as name,\r\n             n as line, updated_at\r\n      from lines\r\n      where line_text ~ '^\\s*#+\\s+'\r\n    )\r\n    select * from heads\r\n    limit %6$s\r\n  $f$,\r\n    cols.path_col, cols.content_col, cols.updated_col,\r\n    files_tbl::text, p_project_id::text, p_max_results::text\r\n  );\r\n\r\n  return query execute sql;\r\nend;\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_list_symbols_py",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_list_symbols_py(p_project_id uuid, p_max_results integer DEFAULT 1000)\n RETURNS TABLE(file_path text, kind text, name text, line integer, updated_at timestamp with time zone)\n LANGUAGE plpgsql\n STABLE\nAS $function$\r\ndeclare\r\n  files_tbl regclass := cb_resolve_files_table();\r\n  cols record;\r\n  sql text;\r\nbegin\r\n  select * into cols from cb_files_columns();\r\n\r\n  sql := format($f$\r\n    with latest as (\r\n      select *\r\n      from (\r\n        select f.*,\r\n               row_number() over (partition by %1$I order by %3$I desc nulls last) as rn\r\n        from %4$s f\r\n        where f.project_id = %5$L::uuid\r\n          and lower(coalesce(f.file_extension,'')) = 'py'\r\n      ) x\r\n      where rn = 1\r\n    ),\r\n    lines as (\r\n      select\r\n        %1$I as file_path,\r\n        %3$I as updated_at,\r\n        regexp_split_to_table(%2$I, E'\\n') with ordinality as (line_text, n)\r\n      from latest\r\n    ),\r\n    defs as (\r\n      select file_path, 'def'::text as kind,\r\n             (regexp_matches(line_text, '^\\s*def\\s+([A-Za-z_][A-Za-z0-9_]*)\\s*\\('))[1] as name,\r\n             n as line, updated_at\r\n      from lines\r\n      where line_text ~ '^\\s*def\\s+[A-Za-z_]'\r\n    ),\r\n    clss as (\r\n      select file_path, 'class'::text as kind,\r\n             (regexp_matches(line_text, '^\\s*class\\s+([A-Za-z_][A-Za-z0-9_]*)\\s*[\\(:]'))[1] as name,\r\n             n as line, updated_at\r\n      from lines\r\n      where line_text ~ '^\\s*class\\s+[A-Za-z_]'\r\n    )\r\n    select * from defs\r\n    union all\r\n    select * from clss\r\n    limit %6$s\r\n  $f$,\r\n    cols.path_col, cols.content_col, cols.updated_col,\r\n    files_tbl::text, p_project_id::text, p_max_results::text\r\n  );\r\n\r\n  return query execute sql;\r\nend;\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_match_routes",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_match_routes(p_project_id uuid, p_q text, p_max_results integer DEFAULT 50)\n RETURNS TABLE(file_path text, method text, route text, score real, updated_at timestamp with time zone)\n LANGUAGE sql\n STABLE\nAS $function$\r\n  with routes as (\r\n    select * from cb_list_routes(p_project_id, 2000)\r\n  ),\r\n  scored as (\r\n    select\r\n      r.file_path,\r\n      r.method,\r\n      r.route,\r\n      r.updated_at,\r\n      greatest(\r\n        similarity(lower(r.route), lower(p_q)) * 0.7,\r\n        similarity(lower(r.file_path), lower(p_q)) * 0.4\r\n      )\r\n      +\r\n      ts_rank(\r\n        to_tsvector('simple', unaccent(lower(replace(r.route,'/',' ')))),\r\n        plainto_tsquery('simple', unaccent(lower(p_q)))\r\n      ) * 0.5\r\n      as score\r\n    from routes r\r\n  )\r\n  select file_path, method, route, score::real, updated_at\r\n  from scored\r\n  where score > 0\r\n  order by score desc, updated_at desc\r\n  limit p_max_results;\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_match_symbols",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_match_symbols(p_project_id uuid, p_q text, p_max_results integer DEFAULT 50)\n RETURNS TABLE(file_path text, kind text, name text, line integer, score real, updated_at timestamp with time zone)\n LANGUAGE sql\n STABLE\nAS $function$\r\n  with sym as (\r\n    select * from cb_list_symbols_py(p_project_id, 2000)\r\n    union all\r\n    select * from cb_list_symbols_js(p_project_id, 2000)\r\n    union all\r\n    select * from cb_list_symbols_md(p_project_id, 2000)\r\n  ),\r\n  scored as (\r\n    select\r\n      file_path, kind, name, line, updated_at,\r\n      greatest(\r\n        similarity(lower(name), lower(p_q)) * 0.8,\r\n        similarity(lower(file_path), lower(p_q)) * 0.4\r\n      )\r\n      +\r\n      ts_rank(\r\n        to_tsvector('simple', unaccent(lower(name))),\r\n        plainto_tsquery('simple', unaccent(lower(p_q)))\r\n      ) * 0.5\r\n      as score\r\n    from sym\r\n  )\r\n  select file_path, kind, name, line, score::real, updated_at\r\n  from scored\r\n  where score > 0\r\n  order by score desc, updated_at desc\r\n  limit p_max_results;\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_message_embeddings_set_project_id",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_message_embeddings_set_project_id()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\r\nbegin\r\n  if NEW.project_id is null then\r\n    select c.project_id\r\n      into NEW.project_id\r\n    from public.cb_messages m\r\n    join public.cb_conversations c\r\n      on c.id = m.conversation_id\r\n    where m.id = NEW.message_id;\r\n\r\n    if NEW.project_id is null then\r\n      raise exception 'Could not derive project_id for message_id=%', NEW.message_id;\r\n    end if;\r\n  end if;\r\n  return NEW;\r\nend;\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_next_blocks_to_embed",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_next_blocks_to_embed(p_project text, p_limit integer DEFAULT 100, p_conversation text DEFAULT NULL::text)\n RETURNS TABLE(block_id text, conversation_id text, content text, file_name text, block_type text, created_at timestamp with time zone)\n LANGUAGE plpgsql\nAS $function$\r\nBEGIN\r\n  RETURN QUERY\r\n  SELECT \r\n    b.id::text as block_id,\r\n    m.conversation_id::text,  -- Get conversation_id from the message\r\n    b.content,\r\n    b.file_name,\r\n    b.kind as block_type,\r\n    m.created_at  -- Use message created_at since blocks don't have it\r\n  FROM cb_blocks b\r\n  JOIN cb_messages m ON b.message_id = m.id  -- Join through messages\r\n  WHERE m.project_id = p_project::uuid\r\n    AND NOT EXISTS (\r\n      SELECT 1 FROM block_embeddings e \r\n      WHERE e.cb_block_id = b.id\r\n    )\r\n    AND (p_conversation IS NULL OR m.conversation_id = p_conversation::uuid)\r\n  ORDER BY m.created_at DESC\r\n  LIMIT p_limit;\r\nEND;\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_next_blocks_to_embed",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_next_blocks_to_embed(p_project uuid, p_limit integer DEFAULT 100)\n RETURNS TABLE(block_id uuid, conversation_id uuid, content text, file_name text, block_type text, created_at timestamp with time zone)\n LANGUAGE sql\nAS $function$\r\n  SELECT \r\n    b.id as block_id,\r\n    m.conversation_id,\r\n    b.content,\r\n    b.file_name,\r\n    COALESCE(b.language, b.kind) as block_type,\r\n    COALESCE(m.created_at, NOW()) as created_at\r\n  FROM cb_blocks b\r\n  INNER JOIN cb_messages m ON m.id = b.message_id\r\n  INNER JOIN cb_conversations c ON c.id = m.conversation_id\r\n  LEFT JOIN block_embeddings be ON be.cb_block_id = b.id\r\n  WHERE \r\n    c.project_id = p_project\r\n    AND be.cb_block_id IS NULL  -- Only blocks without embeddings\r\n    AND COALESCE(LENGTH(b.content), 0) > 0  -- Only blocks with content\r\n  ORDER BY m.created_at DESC NULLS LAST\r\n  LIMIT GREATEST(1, p_limit);\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_next_conversations_to_embed",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_next_conversations_to_embed(p_project uuid, p_limit integer DEFAULT 100)\n RETURNS TABLE(conversation_id uuid, project_id uuid, content text, created_at timestamp with time zone)\n LANGUAGE sql\n STABLE\nAS $function$\r\n  with first_msg as (\r\n    select m.conversation_id,\r\n           (select m2.content\r\n              from public.cb_messages m2\r\n             where m2.conversation_id = m.conversation_id\r\n               and coalesce(length(m2.content),0) > 0\r\n             order by m2.index_in_thread asc nulls last\r\n             limit 1) as first_content\r\n    from public.cb_messages m\r\n    group by m.conversation_id\r\n  )\r\n  select c.id, c.project_id,\r\n         coalesce(nullif(c.summary,''), fm.first_content, c.title, '') as content,\r\n         coalesce(c.started_at, c.inserted_at) as created_at\r\n  from public.cb_conversations c\r\n  left join public.cb_conversation_embeddings ce on ce.conversation_id = c.id\r\n  left join first_msg fm on fm.conversation_id = c.id\r\n  where c.project_id = p_project\r\n    and ce.conversation_id is null\r\n    and coalesce(length(coalesce(nullif(c.summary,''), fm.first_content, c.title, '')),0) > 0\r\n  order by c.started_at desc nulls last\r\n  limit greatest(1, p_limit);\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_next_files_to_embed",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_next_files_to_embed(p_project text, p_limit integer DEFAULT 10, p_conversation text DEFAULT NULL::text)\n RETURNS TABLE(cb_file_id text, conversation_id text, content text, file_name text, file_type text)\n LANGUAGE plpgsql\nAS $function$\r\nBEGIN\r\n  RETURN QUERY\r\n  SELECT \r\n    f.id::text as cb_file_id,\r\n    f.conversation_id::text,\r\n    f.content,\r\n    f.file_name,\r\n    f.file_type\r\n  FROM cb_files f\r\n  WHERE f.project_id = p_project::uuid\r\n    AND NOT EXISTS (\r\n      SELECT 1 FROM cb_file_embeddings e \r\n      WHERE e.cb_file_id = f.id\r\n    )\r\n    AND (p_conversation IS NULL OR f.conversation_id = p_conversation::uuid)\r\n  ORDER BY f.created_at DESC\r\n  LIMIT p_limit;\r\nEND;\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_next_messages_to_embed",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_next_messages_to_embed(p_project text, p_limit integer DEFAULT 200, p_conversation text DEFAULT NULL::text)\n RETURNS TABLE(message_id text, conversation_id text, content text, created_at timestamp with time zone)\n LANGUAGE plpgsql\nAS $function$\r\nBEGIN\r\n  RETURN QUERY\r\n  SELECT \r\n    m.id::text as message_id,\r\n    m.conversation_id::text,\r\n    m.content,\r\n    m.created_at\r\n  FROM cb_messages m\r\n  WHERE m.project_id = p_project::uuid\r\n    AND NOT EXISTS (\r\n      SELECT 1 FROM cb_message_embeddings e \r\n      WHERE e.message_id = m.id\r\n    )\r\n    AND (p_conversation IS NULL OR m.conversation_id = p_conversation::uuid)  -- NEW: filter\r\n  ORDER BY m.created_at DESC\r\n  LIMIT p_limit;\r\nEND;\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_next_messages_to_embed",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_next_messages_to_embed(p_project uuid, p_limit integer DEFAULT 100)\n RETURNS TABLE(message_id uuid, conversation_id uuid, content text, created_at timestamp with time zone)\n LANGUAGE sql\nAS $function$\r\n  SELECT \r\n    m.id as message_id,\r\n    m.conversation_id,\r\n    m.content,\r\n    m.created_at\r\n  FROM cb_messages m\r\n  INNER JOIN cb_conversations c ON c.id = m.conversation_id\r\n  LEFT JOIN cb_message_embeddings me ON me.message_id = m.id\r\n  WHERE \r\n    c.project_id = p_project\r\n    AND me.message_id IS NULL\r\n    AND COALESCE(LENGTH(m.content), 0) > 0\r\n  ORDER BY m.created_at DESC NULLS LAST\r\n  LIMIT GREATEST(1, p_limit);\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_norm",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_norm(s text)\n RETURNS text\n LANGUAGE sql\n IMMUTABLE\nAS $function$\r\n  SELECT regexp_replace(lower(coalesce(s,'')), '\\s+', ' ', 'g')\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_release_project_lock",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_release_project_lock(p_project_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SET search_path TO 'public'\nAS $function$\r\nbegin\r\n  perform pg_advisory_unlock(hashtext(p_project_id::text));\r\nend\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_resolve_files_table",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_resolve_files_table()\n RETURNS regclass\n LANGUAGE plpgsql\nAS $function$\r\ndeclare\r\n  candidates text[] := array['cb_files','files'];\r\n  t regclass;\r\n  name text;\r\nbegin\r\n  foreach name in array candidates loop\r\n    t := to_regclass(name);\r\n    if t is not null then\r\n      return t;\r\n    end if;\r\n  end loop;\r\n\r\n  raise exception 'No files table found. Expected one of: %', candidates;\r\nend;\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_search_entities",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_search_entities(p_project_id uuid, p_query text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)\n RETURNS TABLE(entity_id uuid, name text, type text, mention_count bigint)\n LANGUAGE sql\nAS $function$\r\n  with\r\n  phrases as (\r\n    -- array of quoted phrases (0..N)\r\n    select coalesce(array_agg(m[1]), '{}')::text[] as arr\r\n    from regexp_matches(coalesce(p_query,''), '\"([^\"]+)\"', 'g') m\r\n  ),\r\n  terms as (\r\n    -- array of remaining AND terms (normalized)\r\n    select nullif(regexp_split_to_array(\r\n             public.cb_norm(regexp_replace(coalesce(p_query,''), '\"[^\"]+\"', ' ', 'g')),\r\n             '\\s+'\r\n           ), array[''])::text[] as arr\r\n  ),\r\n  base as (\r\n    select *\r\n    from public.v_cb_entity_search\r\n    where project_id = p_project_id\r\n  ),\r\n  phr as (\r\n    -- keep rows if no phrases OR all phrases match name/canonical\r\n    select b.*\r\n    from base b, phrases p\r\n    where cardinality(p.arr) = 0\r\n       or (\r\n         select bool_and(\r\n           b.name ilike '%'||ph||'%' or b.canonical ilike '%'||public.cb_norm(ph)||'%'\r\n         )\r\n         from unnest(p.arr) ph\r\n       )\r\n  ),\r\n  filt as (\r\n    -- keep rows if no terms OR all terms match name/canonical\r\n    select b.*\r\n    from phr b, terms t\r\n    where cardinality(t.arr) = 0\r\n       or (\r\n         select bool_and(\r\n           b.name ilike '%'||tt||'%' or b.canonical ilike '%'||tt||'%'\r\n         )\r\n         from unnest(t.arr) tt\r\n       )\r\n  )\r\n  select entity_id, name, type, mention_count\r\n  from filt\r\n  order by mention_count desc, name asc\r\n  limit p_limit offset p_offset;\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_set_statement_timeout",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_set_statement_timeout(ms integer)\n RETURNS void\n LANGUAGE sql\nAS $function$\r\n  select set_config('statement_timeout', ms::text, true);\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_try_project_lock",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_try_project_lock(p_project_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'public'\nAS $function$\r\ndeclare ok boolean;\r\nbegin\r\n  ok := pg_try_advisory_lock(hashtext(p_project_id::text));\r\n  return jsonb_build_object('ok', ok);\r\nend\r\n$function$\n"
  },
  {
    "section": "FUNCTIONS",
    "name": "cb_upsert_entity_mention",
    "definition": "CREATE OR REPLACE FUNCTION public.cb_upsert_entity_mention(p_project_id uuid, p_name text, p_type text DEFAULT NULL::text, p_message_id uuid DEFAULT NULL::uuid, p_cb_file_id uuid DEFAULT NULL::uuid, p_block_id uuid DEFAULT NULL::uuid, p_snippet text DEFAULT NULL::text)\n RETURNS uuid\n LANGUAGE plpgsql\nAS $function$\r\nDECLARE\r\n  v_canon text := public.cb_norm(p_name);\r\n  v_entity_id uuid;\r\nBEGIN\r\n  INSERT INTO public.cb_entities (project_id, name, type, canonical)\r\n  VALUES (p_project_id, p_name, p_type, v_canon)\r\n  ON CONFLICT (project_id, canonical)\r\n  DO UPDATE SET name = excluded.name, type = coalesce(excluded.type, public.cb_entities.type)\r\n  RETURNING id INTO v_entity_id;\r\n  \r\n  INSERT INTO public.cb_entity_mentions (project_id, entity_id, message_id, cb_file_id, block_id, snippet)\r\n  VALUES (p_project_id, v_entity_id, p_message_id, p_cb_file_id, p_block_id, p_snippet);\r\n  \r\n  RETURN v_entity_id;\r\nEND;\r\n$function$\n"
  },
